-- Queries for the projects table. Generated into storage/generated by sqlc.
-- See sqlc.yaml at the project root for configuration.
--
-- NOTE: R1.2 introduces dynamic-SQL needs (cursor pagination, conditional
-- search filters, fuzzy resolve with trigram operators) that don't fit
-- sqlc's static-query model. The R1.2 implementation in
-- internal/projects/*.go uses raw pgx queries against the pool. The
-- queries below remain as the canonical sqlc surface for reads/writes
-- that other packages (auth bootstrap, future R1.3 issue handlers) may
-- still call through.

-- GetProjectByID reads one project only through the access barrier
-- (sk-674.18 T010): the row comes back only when the caller sees it — the
-- access relation, skein_project_visible (migration 000067). A missing and an
-- inaccessible project are the same pgx.ErrNoRows (INV-3). There is no
-- unbarriered read of a project by id in this surface, and no global count.
-- name: GetProjectByID :one
SELECT id, name, id_prefix, default_id_mode, description,
       created_by, created_at, updated_at, metadata
FROM projects
WHERE id = sqlc.arg(id)
  AND skein_project_visible(sqlc.arg(caller)::uuid, id);
